import functools

def is_end(s):
    if not s: return True
    if all(x == 0 for x in s): return True
    n = len(s)
    s_sum = sum(s)
    for i in range(n):
        if s[i] > s_sum - s[i]:
            return True
    return False

@functools.lru_cache(None)
def solve(s):
    s = tuple(sorted(s))
    if is_end(s):
        return len(s)

    best_for_a = -1
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n):
            x, y = s[i], s[j]
            remaining = list(s)
            remaining.pop(j)
            remaining.pop(i)

            s1 = tuple(sorted(remaining + [x + y]))
            s2 = tuple(sorted(remaining + [abs(x - y)]))

            val1 = solve(s1)
            val2 = solve(s2)

            b_choice = min(val1, val2)
            if b_choice > best_for_a:
                best_for_a = b_choice
    return best_for_a

print(f"N=16, cookies={solve(tuple([1]*16))}")
